// Conditional Types: T extends U ? X : Y
type IsString<T> = T extends string ? true : false;
type A = IsString<'hello'>;  // true
type B = IsString<123>;      // false

// Infer — извлечение типов внутри conditional:
type ReturnType<T> = T extends (...args: any[]) => infer R ? R : never;
type ParamType<T> = T extends (arg: infer P) => any ? P : never;

function foo(s: string): number { return s.length; }
type FooReturn = ReturnType<typeof foo>;  // number
type FooParam = ParamType<typeof foo>;    // string

// Distributive conditional types (over unions):
type ToArray<T> = T extends any ? T[] : never;
type Result = ToArray<string | number>;  // string[] | number[] (распределяется!)

// Non-distributive: обернуть в tuple
type ToArrayNonDist<T> = [T] extends [any] ? T[] : never;
type Result2 = ToArrayNonDist<string | number>;  // (string | number)[]

// Конструирование строковых типов:
type EventName<T extends string> = `on${Capitalize<T>}`;
type ClickEvent = EventName<'click'>;  // 'onClick'

// С unions:
type Direction = 'top' | 'right' | 'bottom' | 'left';
type MarginProps = `margin${Capitalize<Direction>}`;
// 'marginTop' | 'marginRight' | 'marginBottom' | 'marginLeft'

// Pattern matching:
type ParseUrl<T extends string> = T extends `${infer Protocol}://${infer Rest}`
  ? { protocol: Protocol; rest: Rest }
  : never;

type Parsed = ParseUrl<'https://example.com/path'>;
// { protocol: 'https'; rest: 'example.com/path' }

// CSS-in-JS типизация:
type CSSProperty<T> = T extends `${infer Prop}: ${infer Value}` ? { [K in Prop]: Value } : never;

// Key remapping (TS 4.1+):
type Getters<T> = {
  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K]
};

interface User { name: string; age: number; }
type UserGetters = Getters<User>;
// { getName: () => string; getAge: () => number; }

// Filter keys:
type OnlyStrings<T> = {
  [K in keyof T as T[K] extends string ? K : never]: T[K]
};
type UserStrings = OnlyStrings<User>;  // { name: string }

// Deep readonly:
type DeepReadonly<T> = {
  readonly [K in keyof T]: T[K] extends object ? DeepReadonly<T[K]> : T[K]
};

// Built-in utilities:
Partial<T>          // все optional
Required<T>         // все required
Readonly<T>         // все readonly
Pick<T, K>          // выбрать ключи
Omit<T, K>          // исключить ключи
Record<K, T>        // объект с ключами K и значениями T
Exclude<T, U>       // исключить U из T
Extract<T, U>       // оставить только U из T
NonNullable<T>      // убрать null/undefined
Parameters<T>       // tuple параметров функции
ConstructorParameters<T> // параметры конструктора
ReturnType<T>       // возвращаемый тип
InstanceType<T>     // тип экземпляра класса
ThisParameterType<T> // тип this
OmitThisParameter<T> // убрать this

// Constraints:
function merge<T extends object, U extends object>(a: T, b: U): T & U {
  return { ...a, ...b };
}

// Default generics:
interface ApiResponse<T = unknown> {
  data: T;
  status: number;
  error?: string;
}

// Type parameter defaults в type aliases:
type Container<T = string> = { value: T };

// Variance (in/out) — TS 4.7+:
// out — ковариантность (return types)
interface Producer<out T> { make(): T; }
// in — контравариантность (parameter types)
interface Consumer<in T> { consume(t: T): void; }

// Branded types (nominal typing):
type Brand<K, T> = K & { __brand: T };
type UserId = Brand<string, 'UserId'>;
type PostId = Brand<string, 'PostId'>;

function getUser(id: UserId) { /* ... */ }
getUser('123' as UserId);  // OK
// getUser('123' as PostId); // Error!

// Fluent API typing:
class QueryBuilder<T> {
  select<K extends keyof T>(keys: K[]): QueryBuilder<Pick<T, K>> { return this; }
  where<U extends Partial<T>>(cond: U): QueryBuilder<T> { return this; }
  execute(): Promise<T[]> { return Promise.resolve([]); }
}

const users = await new QueryBuilder<User>()
  .select(['name', 'email'])
  .where({ active: true })
  .execute();
// users: Pick<User, 'name' | 'email'>[]

// Discriminated unions для state machines:
type LoadingState = { status: 'loading' };
type SuccessState = { status: 'success'; data: User[] };
type ErrorState = { status: 'error'; error: Error };
type State = LoadingState | SuccessState | ErrorState;

function handle(state: State) {
  switch (state.status) {
    case 'loading': return '...';
    case 'success': return state.data.length;  // state.data доступен!
    case 'error': return state.error.message;
  }
}

// Tree Shaking = удаление unused exports при bundling
// Работает ТОЛЬКО с ES Modules (import/export) — статический анализ!

// ❌ CommonJS — НЕ tree-shakable:
const _ = require('lodash');
_.map([1,2,3], x => x*2); // весь lodash попадает в bundle!

// ✅ ES Modules — tree-shakable:
import { map } from 'lodash-es';
map([1,2,3], x => x*2); // только map + зависимости!

// ✅ Или с babel/plugin-transform-runtime:
import map from 'lodash/map';  // cherry-pick (но не всегда работает)

// package.json библиотеки:
{
  "name": "my-lib",
  "sideEffects": false,  // ВСЁ чистое — можно безопасно удалять неиспользуемое
  // ИЛИ массив файлов с side effects:
  "sideEffects": [
    "*.css",           // CSS импорты имеют side effects
    "./polyfills.js"   // этот файл выполняет код при импорте
  ]
}

// В коде библиотеки — пометьте pure функции:
/* @__PURE__ */ export function helper() { ... }

// Или в package.json exports:
"exports": {
  ".": {
    "import": "./index.mjs",
    "types": "./index.d.ts"
  },
  "./pure": {
    "import": "./pure.mjs",
    "sideEffects": false
  }
}

// webpack.config.js
module.exports = {
  mode: 'production',  // включает optimization
  optimization: {
    usedExports: true,      // пометка unused exports
    sideEffects: true,      // чтение package.json sideEffects
    minimize: true,         // terser minification
    concatenateModules: true, // scope hoisting
    providedExports: true,  // анализ exports
    innerGraph: true,       // глубокий анализ зависимостей (webpack 5.5+)
  },
  // Для библиотек:
  output: {
    library: { type: 'module' },  // ESM output
  },
  experiments: {
    outputModule: true,
  }
};

// Rollup (более агрессивный tree shaking):
export default {
  input: 'src/index.ts',
  output: { format: 'esm', dir: 'dist' },
  treeshake: {
    moduleSideEffects: 'no-external',  // внешние зависимости — без side effects
    propertyReadSideEffects: false,
    unknownGlobalSideEffects: false,
  },
  plugins: [
    typescript(),
    terser({ module: true })
  ]
};

// esbuild (самый быстрый):
