// ❌ Side effects в коде:
console.log('init');  // side effect!
window.global = {};   // side effect!
require('./polyfill'); // side effect!

// ❌ Re-exporting всё (barrel files):
// utils/index.ts
export * from './helpers';  // ВСЁ экспортируется!
export * from './constants';

// ✅ Named exports только нужного:
// utils/helpers.ts
export function map() { ... }
export function filter() { ... }

// utils/index.ts
