// ❌ Dynamic import в условии:
if (condition) {
  const { heavy } = await import('./heavy'); // не tree-shaken!
}

// ✅ Используйте bundler-specific magic comments:
const { heavy } = await import(/* webpackChunkName: "heavy" */ './heavy');

