// tests/setup.ts
import { PostgreSqlContainer, StartedPostgreSqlContainer } from '@testcontainers/postgresql';
import { GenericContainer, StartedTestContainer } from 'testcontainers';

let pgContainer: StartedPostgreSqlContainer;
let redisContainer: StartedTestContainer;

export async function setup() {
  pgContainer = await new PostgreSqlContainer('postgres:16-alpine')
    .withDatabase('testdb')
    .withUsername('test')
    .withPassword('test')
    .start();

  redisContainer = await new GenericContainer('redis:7-alpine')
    .withExposedPorts(6379)
    .start();

  // Set env vars для приложения
  process.env.DATABASE_URL = pgContainer.getConnectionUri();
  process.env.REDIS_URL = `redis://${redisContainer.getHost()}:${redisContainer.getMappedPort(6379)}`;
}

export async function teardown() {
  await pgContainer?.stop();
  await redisContainer?.stop();
}

// tests/user.integration.test.ts
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { setup, teardown } from './setup';
import { UserRepository } from '../src/repositories/user';

describe('UserRepository Integration', () => {
  let repo: UserRepository;

  beforeAll(async () => {
    await setup();
    repo = new UserRepository();
    await repo.migrate(); // run migrations
  });

  afterAll(async () => {
    await teardown();
  });

  it('should create and find user', async () => {
    const user = await repo.create({ email: 'test@example.com', name: 'Test' });
    expect(user.id).toBeDefined();

    const found = await repo.findById(user.id);
    expect(found?.email).toBe('test@example.com');
  });
});

// Consumer test (frontend/client):
import { PactV3, MatchersV3 } from '@pact-foundation/pact';
import { UserApiClient } from './api/client';

const { like, eachLike } = MatchersV3;

const provider = new PactV3({
  consumer: 'web-app',
  provider: 'user-api',
  dir: './pacts',
});

describe('UserApiClient contract', () => {
  it('returns users list', async () => {
    await provider
      .given('users exist')
      .uponReceiving('a request for users')
      .withRequest({
        method: 'GET',
        path: '/api/users',
        headers: { Accept: 'application/json' },
      })
      .willRespondWith({
        status: 200,
        headers: { 'Content-Type': 'application/json' },
        body: eachLike({
          id: like('123'),
          name: like('John'),
          email: like('john@example.com'),
        }),
      })
      .executeTest(async (mockServer) => {
        const client = new UserApiClient(mockServer.url);
        const users = await client.getUsers();
        expect(users).toHaveLength(1);
        expect(users[0].name).toBe('John');
      });
  });
});

